<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { api } from '@wippy-fe/proxy'
import { useEvents, useProps } from '@wippy-fe/webcomponent-vue'
import type { PickerProps, PickerEvents } from '../types'
interface Connection { component_id:string; name?:string; connection_state?:string }
interface Tool { id:string; name:string; description:string }
const props=useProps<PickerProps>(); const emit=useEvents<PickerEvents>()
const connections=ref<Connection[]>([]), tools=ref<Tool[]>([]), connectionId=ref(''), selected=ref<string[]>([]), prefix=ref('mcp'), query=ref(''), loadingConnections=ref(true), loadingTools=ref(false), error=ref('')
const initialSelection=ref<string[]|undefined>(undefined)
watch(()=>props.value.config,c=>{connectionId.value=c?.connection_id||'';initialSelection.value=c?.selected_tools;selected.value=c?.selected_tools||[];prefix.value=c?.tool_prefix||'mcp'},{immediate:true})
const current=computed(()=>connections.value.find(c=>c.component_id===connectionId.value))
const filtered=computed(()=>{const q=query.value.trim().toLowerCase();return q?tools.value.filter(t=>(t.name+' '+t.description).toLowerCase().includes(q)):tools.value})
const selectedSet=computed(()=>new Set(selected.value)); const allSelected=computed(()=>tools.value.length>0&&tools.value.every(t=>selectedSet.value.has(t.id)))
function publish(){emit('config-changed',{connection_id:connectionId.value||undefined,selected_tools:selected.value,tool_prefix:prefix.value.trim()||'mcp'})}
function toggle(id:string){selected.value=selectedSet.value.has(id)?selected.value.filter(x=>x!==id):[...selected.value,id];publish()}
function selectVisible(){selected.value=[...new Set([...selected.value,...filtered.value.map(t=>t.id)])];publish()}
function clear(){selected.value=[];publish()}
async function discover(preserve=false){tools.value=[];query.value='';if(!connectionId.value){selected.value=[];publish();return}loadingTools.value=true;error.value='';try{const {data}=await api.post(`/api/v1/connections/${encodeURIComponent(connectionId.value)}/discover_resources`,{});if(!data?.success)throw new Error(data?.error||'Tool discovery failed');tools.value=(data.resources||[]).filter((r: {selectable?: boolean})=>r.selectable).map((r: {id: string; name?: string; description?: string})=>({id:String(r.id),name:String(r.name||r.id),description:String(r.description||'No description provided.')}));const allowed=new Set(tools.value.map(t=>t.id));selected.value=preserve&&initialSelection.value!==undefined?initialSelection.value.filter(id=>allowed.has(id)):tools.value.map(t=>t.id);publish()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loadingTools.value=false}}
async function load(){loadingConnections.value=true;try{const {data}=await api.get('/api/v1/connections?provider=mcp_remote&limit=100');connections.value=data?.connections||[];if(connectionId.value)await discover(true)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loadingConnections.value=false}}load()
</script>
<template><div class="mcp picker"><header class="picker-head"><span><strong>Remote MCP tools</strong><small>Choose the tools this agent may see and call.</small></span><span v-if="selected.length" class="count">{{selected.length}} selected</span></header><label class="field"><span>MCP connection <em>Required</em></span><select v-model="connectionId" :disabled="loadingConnections" @change="initialSelection=undefined;discover(false)"><option value="">{{loadingConnections?'Loading connections…':'Select a connection'}}</option><option v-for="c in connections" :key="c.component_id" :value="c.component_id">{{c.name||c.component_id}}</option></select></label><div v-if="current" class="connection-state"><span class="live-dot"></span><span>{{current.name||'MCP server'}}</span><small>Session starts on demand</small><button type="button" :disabled="loadingTools" @click="discover(true)">Refresh</button></div><label class="field"><span>Tool name prefix</span><input v-model="prefix" maxlength="24" placeholder="mcp" @change="publish"/><small>Prevents names from colliding with the agent's other tools.</small></label><section v-if="connectionId" class="catalog"><div class="catalog-head"><span><strong>Allowed tools</strong><small v-if="tools.length">{{selected.length}} of {{tools.length}}</small></span><span class="catalog-actions"><button type="button" :disabled="allSelected" @click="selectVisible">Select {{query?'matches':'all'}}</button><button type="button" :disabled="!selected.length" @click="clear">Clear</button></span></div><label v-if="tools.length" class="search"><span aria-hidden="true">⌕</span><input v-model="query" type="search" placeholder="Search tools" aria-label="Search MCP tools"/><kbd>{{filtered.length}}</kbd></label><div v-if="loadingTools" class="loading-list" aria-live="polite"><span v-for="n in 4" :key="n"></span></div><div v-else-if="filtered.length" class="tool-list"><label v-for="tool in filtered" :key="tool.id" class="tool-row" :class="{selected:selectedSet.has(tool.id)}"><input type="checkbox" :checked="selectedSet.has(tool.id)" @change="toggle(tool.id)"/><span class="checkmark">✓</span><span class="tool-copy"><strong>{{tool.name}}</strong><small>{{tool.description}}</small></span></label></div><div v-else-if="tools.length" class="empty">No tools match “{{query}}”.</div><div v-else-if="!loadingTools&&!error" class="empty">This server did not expose any tools.</div></section><div v-if="!connections.length&&!loadingConnections" class="empty connection-empty"><strong>No Remote MCP connections</strong><small>Create one from Connections, then return here.</small></div><div v-if="error" class="feedback error" role="alert"><span>!</span><div><strong>Could not load tools</strong><small>{{error}}</small></div></div></div></template>
